// Acceptance for issue #17 (asset-tooling materialization and reuse), written by an independent
// acceptance context before the implementation. Contract: src/assets/materialize.test.ts (header).
//
// In the Pages app (the same Vite build the Pages workflow publishes, from a clean checkout):
// - the fixture project `moenarch-materialized-audio` is in the catalog, opens by pointer from the
//   catalog navigation, plays and pauses with the toolbar (pointer) and Space (keyboard), without
//   page errors;
// - each of its audio slots, two generated by asset-tooling operations during the build
//   (audio.oscillator@1, audio.adsr@1) and one local, plays in the Player from a same-origin URL
//   containing the slot's sha256, and the served bytes hash to the locked identity;
// - the build publishes each generated object at `assets/sha256/<sha256>.wav` (relative to the app
//   base), in the served app and in the Pages artifact `dist/` (`bun run build`; `bun run verify`
//   builds it before Playwright).
// The digests were computed independently with asset-tooling 61d71f7.
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

import { expect, test, type Page } from '@playwright/test';

import { narrationSchedule } from '../src/spec/narration-schedule.ts';
import { assertVideoSpec } from '../src/spec/video-spec.ts';

const ROOT = new URL('..', import.meta.url).pathname;
const PROJECT_ID = 'moenarch-materialized-audio';
const TITLE = 'Moenarch materialized audio';
const EXPECTED = {
  'narration.tone': { sha256: 'd48c98beddf5202012336bdfd5269c5d392fd2b482c24bd0abf3a0f0e19266e5', byteLength: 32044 },
  'narration.shaped': { sha256: '4b3b9d6b07fd861f13bbec2a90686f29d31f2d29276877099ef8b9ed231b813f', byteLength: 32044 },
  'narration.local': { sha256: '7fcbe09842d61da37fbc92be7a47dabc0408b44a2342341ecf655174791d0ed9', byteLength: 19644 },
} as const;
const GENERATED = ['narration.tone', 'narration.shaped'] as const;

let cached: ReturnType<typeof assertVideoSpec> | null = null;
function spec() {
  cached ??= assertVideoSpec(JSON.parse(readFileSync(join(ROOT, 'src', 'spec', 'fixtures', `${PROJECT_ID}.videospec.json`), 'utf8')));
  return cached;
}

const controls = (page: Page) => page.getByRole('group', { name: 'Video controls' });

async function expectPlaying(page: Page, playing: boolean) {
  await expect(controls(page).getByRole('button', { name: playing ? 'Pause video' : 'Play video', exact: true })).toBeVisible();
  expect(await page.evaluate(() => window.__latencyPlayer!.isPlaying())).toBe(playing);
}

async function open(page: Page) {
  const errors: string[] = [];
  page.on('pageerror', (error) => errors.push(error.message));
  await page.goto(`/?project=${PROJECT_ID}`);
  await page.waitForFunction(() => window.__latencyPlayer !== undefined);
  return errors;
}

async function seek(page: Page, frame: number) {
  await page.evaluate(async (target) => {
    const player = window.__latencyPlayer!;
    player.pause();
    player.seekTo(target);
    await new Promise<void>((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));
  }, frame);
  await expect.poll(() => page.evaluate(() => window.__latencyPlayer!.getCurrentFrame())).toBe(frame);
}

/** Fetches a URL in the page and returns its status, origin, sha256 and length. */
function served(page: Page, url: string) {
  return page.evaluate(async (target) => {
    const response = await fetch(target);
    const bytes = await response.arrayBuffer();
    const digest = await crypto.subtle.digest('SHA-256', bytes);
    return {
      status: response.status,
      origin: new URL(response.url).origin,
      sha256: [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join(''),
      byteLength: bytes.byteLength,
    };
  }, url);
}

function audioSources(page: Page, digest: string) {
  return page
    .locator(`[data-composition-id="${PROJECT_ID}"]`)
    .evaluate(
      (player, needle) =>
        [...player.querySelectorAll('audio')]
          .map((audio) => audio.currentSrc || audio.src)
          .filter((src) => /^https?:/.test(src) && src.includes(needle)),
      digest,
    );
}

test('the fixture locks the independently computed asset-tooling outputs', () => {
  const slots = spec().assets as unknown as { id: string; asset: { sha256: string; byteLength: number; mediaType: string } }[];
  expect(Object.fromEntries(slots.map((slot) => [slot.id, { sha256: slot.asset.sha256, byteLength: slot.asset.byteLength }]))).toEqual(EXPECTED);
  expect(slots.every((slot) => slot.asset.mediaType === 'audio/wav')).toBe(true);
});

test('the materialized project opens from the catalog and plays with pointer and keyboard', async ({ page }) => {
  const errors: string[] = [];
  page.on('pageerror', (error) => errors.push(error.message));
  await page.goto('/?project=latency-explainer');
  await page.waitForFunction(() => window.__latencyPlayer !== undefined);
  const nav = page.getByRole('navigation', { name: /projects/i });
  await nav.getByRole('link', { name: TITLE, exact: true }).click();
  await expect(page).toHaveURL(new RegExp(`[?&]project=${PROJECT_ID}(&|$)`));
  const player = page.locator(`[data-composition-id="${PROJECT_ID}"]`);
  await expect(player).toBeVisible();

  await controls(page).getByRole('button', { name: 'Play video', exact: true }).click();
  // A pointer visit to empty composition background establishes the video context for Space.
  await player.click({ position: { x: 8, y: 8 } });
  await expectPlaying(page, true);
  await page.keyboard.press('Space');
  await expectPlaying(page, false);
  const paused = await page.evaluate(() => window.__latencyPlayer!.getCurrentFrame());
  await page.keyboard.press('Space');
  await expectPlaying(page, true);
  await expect.poll(() => page.evaluate(() => window.__latencyPlayer!.getCurrentFrame())).toBeGreaterThan(paused);
  expect(errors).toEqual([]);
});

test('every slot, generated or local, plays from its content-addressed URL with the locked bytes', async ({ page, baseURL }) => {
  const errors = await open(page);
  const schedule = narrationSchedule(spec());
  const heard = new Set<string>();
  for (const scene of schedule.scenes) {
    const segment = scene.audio?.segments[0];
    if (!segment) continue;
    const slotId = scene.audio!.asset as keyof typeof EXPECTED;
    const expected = EXPECTED[slotId];
    expect(expected, `scene ${scene.id} plays a fixture slot`).toBeDefined();
    await seek(page, segment.from + Math.floor(segment.durationInFrames / 2));
    await expect.poll(() => audioSources(page, expected.sha256), { message: slotId }).toHaveLength(1);
    const [src] = await audioSources(page, expected.sha256);
    expect(await served(page, src)).toEqual({ status: 200, origin: new URL(baseURL!).origin, ...expected });
    heard.add(slotId);
  }
  expect([...heard].sort()).toEqual(Object.keys(EXPECTED).sort());
  expect(errors).toEqual([]);
});

test('the build serves generated audio at assets/sha256/<sha256>.wav with the matching hash', async ({ page, baseURL }) => {
  await open(page);
  for (const slotId of GENERATED) {
    const expected = EXPECTED[slotId];
    const url = new URL(`assets/sha256/${expected.sha256}.wav`, await page.evaluate(() => document.baseURI)).href;
    expect(await served(page, url), slotId).toEqual({ status: 200, origin: new URL(baseURL!).origin, ...expected });
  }
});

test('the Pages artifact (dist/) contains each generated object at its content-addressed path', () => {
  const dist = join(ROOT, 'dist');
  expect(existsSync(join(dist, 'index.html')), 'run `bun run build` first (bun run verify does)').toBe(true);
  for (const slotId of GENERATED) {
    const expected = EXPECTED[slotId];
    const file = join(dist, 'assets', 'sha256', `${expected.sha256}.wav`);
    expect(existsSync(file), `${slotId}: ${file}`).toBe(true);
    const bytes = readFileSync(file);
    expect({ sha256: createHash('sha256').update(bytes).digest('hex'), byteLength: bytes.length }, slotId).toEqual(expected);
  }
});
